{
  "returncode": 0,
  "output": "//! Quizzy — a live quiz for conference talks. This is the moderator release:
//! preparing quizzes, questions and options, plus a playable preview.
//!
//! Run with: PORT=3000 SECRET_KEY_BASE=... QUIZZY_MODERATOR_USERNAME=... \
//!           QUIZZY_MODERATOR_PASSWORD=... ./bin/serve
//!
//! SECRET_KEY_BASE is accepted for forward compatibility (session signing in
//! later releases); this release keeps no session state.

mod db;
mod httpd;
mod json;
mod routes;
mod transfer;
mod views;

use std::sync::Arc;

fn main() {
    let port: u16 = std::env::var("PORT")
        .ok()
        .and_then(|p| p.parse().ok())
        .unwrap_or(3000);
    let state = Arc::new(routes::State {
        db_path: std::env::var("QUIZZY_DATABASE_PATH")
            .unwrap_or_else(|_| "storage/quizzy.db".to_string()),
        moderator_username: std::env::var("QUIZZY_MODERATOR_USERNAME").unwrap_or_default(),
        moderator_password: std::env::var("QUIZZY_MODERATOR_PASSWORD").unwrap_or_default(),
    });

    // Everything the app stores lives under storage/.
    if let Some(parent) = std::path::Path::new(&state.db_path).parent() {
        std::fs::create_dir_all(parent).expect("cannot create storage directory");
    }
    {
        let conn = db::connect(&state.db_path).expect("cannot open the database");
        db::migrate(&conn).expect("cannot migrate the database");
    }

    let server = tiny_http::Server::http(("0.0.0.0", port))
        .unwrap_or_else(|e| panic!("cannot listen on port {port}: {e}"));
    println!("Quizzy is ready on http://0.0.0.0:{port}");
    let server = Arc::new(server);

    let workers = std::thread::available_parallelism().map(|n| n.get().clamp(8, 32)).unwrap_or(8);
    let mut handles = Vec::new();
    for _ in 0..workers {
        let server = Arc::clone(&server);
        let state = Arc::clone(&state);
        handles.push(std::thread::spawn(move || loop {
            match server.recv() {
                Ok(request) => {
                    let state = Arc::clone(&state);
                    httpd::dispatch(request, &move |req| routes::handle(req, &state));
                }
                Err(_) => continue,
            }
        }));
    }
    for h in handles {
        let _ = h.join();
    }
}
"
}

{
  "returncode": 0,
  "output": "//! SQLite storage for Quizzy.
//!
//! Schema: quizzes have questions (ordered by `position`), questions have
//! options (ordered by `position`). Deleting a quiz cascades to its questions
//! and options through foreign keys.

use rusqlite::{Connection, Result, params};

#[derive(Debug, Clone)]
pub struct Quiz {
    pub id: i64,
    pub title: String,
}

#[derive(Debug, Clone)]
pub struct Question {
    pub id: i64,
    pub quiz_id: i64,
    pub position: i64,
    pub text: String,
    pub active: bool,
    pub options: Vec<Opt>,
}

#[derive(Debug, Clone)]
pub struct Opt {
    pub id: i64,
    pub text: String,
    pub correct: bool,
}

pub struct QuizSummary {
    pub quiz: Quiz,
    pub total_questions: i64,
    pub active_questions: i64,
}

/// Open a connection with the pragmas every connection needs.
pub fn connect(path: &str) -> Result<Connection> {
    let conn = Connection::open(path)?;
    conn.execute_batch(
        "PRAGMA foreign_keys = ON;
         PRAGMA busy_timeout = 5000;",
    )?;
    Ok(conn)
}

/// Create the schema if it does not exist yet. Safe to run on every boot.
pub fn migrate(conn: &Connection) -> Result<()> {
    conn.execute_batch(
        "PRAGMA journal_mode = WAL;

         CREATE TABLE IF NOT EXISTS quizzes (
           id         INTEGER PRIMARY KEY AUTOINCREMENT,
           title      TEXT NOT NULL,
           created_at TEXT NOT NULL DEFAULT (datetime('now'))
         );

         CREATE TABLE IF NOT EXISTS questions (
           id       INTEGER PRIMARY KEY AUTOINCREMENT,
           quiz_id  INTEGER NOT NULL REFERENCES quizzes(id) ON DELETE CASCADE,
           position INTEGER NOT NULL,
           text     TEXT NOT NULL,
           active   INTEGER NOT NULL DEFAULT 1
         );
         CREATE INDEX IF NOT EXISTS idx_questions_quiz ON questions(quiz_id, position);

         CREATE TABLE IF NOT EXISTS options (
           id          INTEGER PRIMARY KEY AUTOINCREMENT,
           question_id INTEGER NOT NULL REFERENCES questions(id) ON DELETE CASCADE,
           position    INTEGER NOT NULL,
           text        TEXT NOT NULL,
           correct     INTEGER NOT NULL DEFAULT 0
         );
         CREATE INDEX IF NOT EXISTS idx_options_question ON options(question_id, position);",
    )?;
    Ok(())
}

// ---------- Quizzes ----------

pub fn list_quizzes(conn: &Connection) -> Result<Vec<QuizSummary>> {
    let mut stmt = conn.prepare(
        "SELECT q.id, q.title,
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id),
                (SELECT COUNT(*) FROM questions WHERE quiz_id = q.id AND active = 1)
         FROM quizzes q ORDER BY q.id",
    )?;
    let rows = stmt.query_map([], |row| {
        Ok(QuizSummary {
            quiz: Quiz { id: row.get(0)?, title: row.get(1)? },
            total_questions: row.get(2)?,
            active_questions: row.get(3)?,
        })
    })?;
    rows.collect()
}

pub fn create_quiz(conn: &Connection, title: &str) -> Result<i64> {
    conn.execute("INSERT INTO quizzes (title) VALUES (?1)", params![title])?;
    Ok(conn.last_insert_rowid())
}

pub fn get_quiz(conn: &Connection, id: i64) -> Result<Option<Quiz>> {
    let mut stmt = conn.prepare("SELECT id, title FROM quizzes WHERE id = ?1")?;
    let mut rows = stmt.query(params![id])?;
    match rows.next()? {
        Some(row) => Ok(Some(Quiz { id: row.get(0)?, title: row.get(1)? })),
        None => Ok(None),
    }
}

pub fn update_quiz(conn: &Connection, id: i64, title: &str) -> Result<()> {
    conn.execute("UPDATE quizzes SET title = ?2 WHERE id = ?1", params![id, title])?;
    Ok(())
}

pub fn delete_quiz(conn: &Connection, id: i64) -> Result<()> {
    conn.execute("DELETE FROM quizzes WHERE id = ?1", params![id])?;
    Ok(())
}

/// Insert a quiz with all its questions in one transaction, so an import
/// either lands completely or not at all. `questions` is a list of
/// (text, active, options) triples in display order.
pub fn import_quiz(
    conn: &mut Connection,
    title: &str,
    questions: &[(String, bool, Vec<(String, bool)>)],
) -> Result<i64> {
    let tx = conn.transaction()?;
    let quiz_id = create_quiz(&tx, title)?;
    for (text, active, options) in questions {
        create_question(&tx, quiz_id, text, *active, options)?;
    }
    tx.commit()?;
    Ok(quiz_id)
}

// ---------- Questions ----------

pub fn list_questions(conn: &Connection, quiz_id: i64) -> Result<Vec<Question>> {
    let mut stmt = conn.prepare(
        "SELECT id, quiz_id, position, text, active FROM questions
         WHERE quiz_id = ?1 ORDER BY position, id",
    )?;
    let rows = stmt.query_map(params![quiz_id], |row| {
        Ok(Question {
            id: row.get(0)?,
            quiz_id: row.get(1)?,
            position: row.get(2)?,
            text: row.get(3)?,
            active: row.get::<_, i64>(4)? != 0,
            options: Vec::new(),
        })
    })?;
    let mut questions: Vec<Question> = rows.collect::<Result<_>>()?;
    for q in &mut questions {
        q.options = list_options(conn, q.id)?;
    }
    Ok(questions)
}

pub fn get_question(conn: &Connection, id: i64) -> Result<Option<Question>> {
    let mut stmt =
        conn.prepare("SELECT id, quiz_id, position, text, active FROM questions WHERE id = ?1")?;
    let mut rows = stmt.query(params![id])?;
    match rows.next()? {
        Some(row) => {
            let mut q = Question {
                id: row.get(0)?,
                quiz_id: row.get(1)?,
                position: row.get(2)?,
                text: row.get(3)?,
                active: row.get::<_, i64>(4)? != 0,
                options: Vec::new(),
            };
            q.options = list_options(conn, q.id)?;
            Ok(Some(q))
        }
        None => Ok(None),
    }
}

fn list_options(conn: &Connection, question_id: i64) -> Result<Vec<Opt>> {
    let mut stmt = conn.prepare(
        "SELECT id, text, correct FROM options WHERE question_id = ?1 ORDER BY position, id",
    )?;
    let rows = stmt.query_map(params![question_id], |row| {
        Ok(Opt { id: row.get(0)?, text: row.get(1)?, correct: row.get::<_, i64>(2)? != 0 })
    })?;
    rows.collect()
}

/// `options` is a list of (text, correct) pairs in display order.
pub fn create_question(
    conn: &Connection,
    quiz_id: i64,
    text: &str,
    active: bool,
    options: &[(String, bool)],
) -> Result<i64> {
    let position: i64 = conn.query_row(
        "SELECT COALESCE(MAX(position), 0) + 1 FROM questions WHERE quiz_id = ?1",
        params![quiz_id],
        |row| row.get(0),
    )?;
    conn.execute(
        "INSERT INTO questions (quiz_id, position, text, active) VALUES (?1, ?2, ?3, ?4)",
        params![quiz_id, position, text, active as i64],
    )?;
    let id = conn.last_insert_rowid();
    insert_options(conn, id, options)?;
    Ok(id)
}

/// Replace text/active/options of an existing question (position untouched).
pub fn update_question(
    conn: &Connection,
    id: i64,
    text: &str,
    active: bool,
    options: &[(String, bool)],
) -> Result<()> {
    conn.execute(
        "UPDATE questions SET text = ?2, active = ?3 WHERE id = ?1",
        params![id, text, active as i64],
    )?;
    conn.execute("DELETE FROM options WHERE question_id = ?1", params![id])?;
    insert_options(conn, id, options)?;
    Ok(())
}

fn insert_options(conn: &Connection, question_id: i64, options: &[(String, bool)]) -> Result<()> {
    let mut stmt =
        conn.prepare("INSERT INTO options (question_id, position, text, correct) VALUES (?1, ?2, ?3, ?4)")?;
    for (i, (text, correct)) in options.iter().enumerate() {
        stmt.execute(params![question_id, (i + 1) as i64, text, *correct as i64])?;
    }
    Ok(())
}

pub fn delete_question(conn: &Connection, id: i64) -> Result<()> {
    conn.execute("DELETE FROM questions WHERE id = ?1", params![id])?;
    Ok(())
}

pub fn set_question_active(conn: &Connection, id: i64, active: bool) -> Result<()> {
    conn.execute("UPDATE questions SET active = ?2 WHERE id = ?1", params![id, active as i64])?;
    Ok(())
}

/// Swap a question with its neighbour in the quiz's ordering.
pub fn move_question(conn: &Connection, id: i64, dir: &str) -> Result<()> {
    let Some(q) = get_question(conn, id)? else { return Ok(()) };
    let questions = list_questions(conn, q.quiz_id)?;
    let Some(idx) = questions.iter().position(|x| x.id == id) else { return Ok(()) };
    let other = match dir {
        "up" => idx.checked_sub(1),
        "down" => {
            if idx + 1 < questions.len() { Some(idx + 1) } else { None }
        }
        _ => None,
    };
    if let Some(o) = other {
        let a = &questions[idx];
        let b = &questions[o];
        conn.execute("UPDATE questions SET position = ?2 WHERE id = ?1", params![a.id, b.position])?;
        conn.execute("UPDATE questions SET position = ?2 WHERE id = ?1", params![b.id, a.position])?;
    }
    Ok(())
}
"
}

{
  "returncode": 0,
  "output": "//! Thin HTTP plumbing on top of tiny_http: request parsing (query string,
//! urlencoded bodies, Basic auth header) and response construction.

use std::io::Read;
use tiny_http::{Header, Request as TinyRequest, Response, StatusCode};

pub struct Request {
    pub method: String,
    pub path: String,
    pub query: Vec<(String, String)>,
    pub form: Vec<(String, String)>,
    pub authorization: Option<String>,
}

impl Request {
    /// Look up a parameter: form body first, then the query string.
    pub fn param(&self, key: &str) -> Option<&str> {
        self.form
            .iter()
            .chain(self.query.iter())
            .find(|(k, _)| k == key)
            .map(|(_, v)| v.as_str())
    }

    pub fn has_param(&self, key: &str) -> bool {
        self.param(key).is_some()
    }
}

pub struct Resp {
    pub status: u16,
    pub content_type: &'static str,
    pub body: Vec<u8>,
    pub extra_headers: Vec<(String, String)>,
}

impl Resp {
    pub fn html(body: String) -> Resp {
        Resp { status: 200, content_type: "text/html; charset=utf-8", body: body.into_bytes(), extra_headers: vec![] }
    }

    pub fn text(status: u16, body: &str) -> Resp {
        Resp { status, content_type: "text/plain; charset=utf-8", body: body.as_bytes().to_vec(), extra_headers: vec![] }
    }

    /// See Other: the response to every successful POST (post/redirect/get).
    pub fn redirect(location: &str) -> Resp {
        Resp {
            status: 303,
            content_type: "text/plain; charset=utf-8",
            body: Vec::new(),
            extra_headers: vec![("Location".to_string(), location.to_string())],
        }
    }

    pub fn not_found() -> Resp {
        Resp::text(404, "Not found")
    }

    pub fn unauthorized() -> Resp {
        Resp {
            status: 401,
            content_type: "text/plain; charset=utf-8",
            body: b"Authentication required".to_vec(),
            extra_headers: vec![(
                "WWW-Authenticate".to_string(),
                "Basic realm=\"Quizzy moderator\", charset=\"UTF-8\"".to_string(),
            )],
        }
    }
}

/// Entry point called by the worker threads: parse, route, respond.
pub fn dispatch(mut rq: TinyRequest, route: &dyn Fn(&Request) -> Resp) {
    let method = rq.method().to_string();
    let url = rq.url().to_string();
    let authorization = rq
        .headers()
        .iter()
        .find(|h| h.field.equiv("Authorization"))
        .map(|h| h.value.as_str().to_string());

    let mut body = Vec::new();
    if matches!(method.as_str(), "POST" | "PUT" | "PATCH" | "DELETE") {
        let _ = rq.as_reader().take(8 * 1024 * 1024).read_to_end(&mut body);
    }

    let (path, raw_query) = match url.split_once('?') {
        Some((p, q)) => (p.to_string(), q.to_string()),
        None => (url, String::new()),
    };

    let req = Request {
        method,
        path,
        query: parse_urlencoded(raw_query.as_bytes()),
        form: parse_urlencoded(&body),
        authorization,
    };

    let resp = match std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| route(&req))) {
        Ok(resp) => resp,
        Err(_) => Resp::text(500, "Internal server error"),
    };
    respond(rq, resp);
}

fn respond(rq: TinyRequest, resp: Resp) {
    let mut r = Response::from_data(resp.body).with_status_code(StatusCode(resp.status));
    if let Ok(h) = Header::from_bytes("Content-Type", resp.content_type) {
        r.add_header(h);
    }
    for (name, value) in &resp.extra_headers {
        if let Ok(h) = Header::from_bytes(name.as_str(), value.as_str()) {
            r.add_header(h);
        }
    }
    let _ = rq.respond(r);
}

/// Parse an `application/x-www-form-urlencoded` payload (or query string).
pub fn parse_urlencoded(data: &[u8]) -> Vec<(String, String)> {
    let text = String::from_utf8_lossy(data);
    text.split('&')
        .filter(|pair| !pair.is_empty())
        .map(|pair| {
            let (k, v) = pair.split_once('=').unwrap_or((pair, ""));
            (url_decode(k), url_decode(v))
        })
        .collect()
}

fn url_decode(s: &str) -> String {
    let bytes = s.as_bytes();
    let mut out = Vec::with_capacity(bytes.len());
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'+' => {
                out.push(b' ');
                i += 1;
            }
            b'%' if i + 2 < bytes.len() => {
                match (hex_val(bytes[i + 1]), hex_val(bytes[i + 2])) {
                    (Some(h), Some(l)) => {
                        out.push((h << 4) | l);
                        i += 3;
                    }
                    _ => {
                        out.push(bytes[i]);
                        i += 1;
                    }
                }
            }
            c => {
                out.push(c);
                i += 1;
            }
        }
    }
    String::from_utf8_lossy(&out).into_owned()
}

fn hex_val(c: u8) -> Option<u8> {
    match c {
        b'0'..=b'9' => Some(c - b'0'),
        b'a'..=b'f' => Some(c - b'a' + 10),
        b'A'..=b'F' => Some(c - b'A' + 10),
        _ => None,
    }
}

/// Decode the `Authorization: Basic ...` header into (username, password).
pub fn basic_credentials(header: &str) -> Option<(String, String)> {
    let token = header.strip_prefix("Basic ").or_else(|| {
        // tolerate lowercase scheme
        if header.len() > 6 && header[..6].eq_ignore_ascii_case("basic ") {
            Some(&header[6..])
        } else {
            None
        }
    })?;
    let decoded = base64_decode(token.trim())?;
    let text = String::from_utf8_lossy(&decoded);
    let (user, pass) = text.split_once(':')?;
    Some((user.to_string(), pass.to_string()))
}

fn base64_decode(input: &str) -> Option<Vec<u8>> {
    fn val(c: u8) -> Option<u8> {
        match c {
            b'A'..=b'Z' => Some(c - b'A'),
            b'a'..=b'z' => Some(c - b'a' + 26),
            b'0'..=b'9' => Some(c - b'0' + 52),
            b'+' => Some(62),
            b'/' => Some(63),
            _ => None,
        }
    }
    let mut out = Vec::with_capacity(input.len() * 3 / 4);
    let mut acc: u32 = 0;
    let mut nbits = 0;
    for &c in input.as_bytes() {
        if c == b'=' || c == b'\n' || c == b'\r' || c == b' ' {
            continue;
        }
        let v = val(c)? as u32;
        acc = (acc << 6) | v;
        nbits += 6;
        if nbits >= 8 {
            nbits -= 8;
            out.push((acc >> nbits) as u8);
        }
    }
    Some(out)
}
"
}

{
  "returncode": 0,
  "output_head": "//! Request routing and handlers.

use crate::db::{self, Question};
use crate::httpd::{Request, Resp, basic_credentials};
use crate::transfer;
use crate::views;
use rusqlite::Connection;

pub struct State {
    pub db_path: String,
    pub moderator_username: String,
    pub moderator_password: String,
}

const CSS: &str = include_str!("../assets/quizzy.css");
const FONT: &[u8] = include_bytes!("../assets/Inter-latin.woff2");

pub fn handle(req: &Request, state: &State) -> Resp {
    let segments: Vec<&str> = req.path.split('/').filter(|s| !s.is_empty()).collect();
    match (req.method.as_str(), segments.as_slice()) {
        ("GET", ["up"]) => return Resp::text(200, "OK"),
        ("GET", []) => return Resp::redirect("/moderate"),
        ("GET", ["assets", "quizzy.css"]) => {
            return Resp { status: 200, content_type: "text/css; charset=utf-8", body: CSS.as_bytes().to_vec(), extra_headers: vec![] };
        }
        ("GET", ["assets", "Inter-latin.woff2"]) => {
            return Resp { status: 200, content_type: "font/woff2", body: FONT.to_vec(), extra_headers: vec![] };
        }
        ("GET", ["favicon.ico"]) => return Resp { status: 204, content_type: "image/x-icon", body: vec![], extra_headers: vec![] },
        _ => {}
    }
    // Everything else lives in the moderator area and needs authentication.
    if !authorized(req, state) {
        return Resp::unauthorized();
    }
    let mut conn = match db::connect(&state.db_path) {
        Ok(c) => c,
        Err(_) => return Resp::text(500, "Database error"),
    };
    moderate(req, &mut conn, &segments)
}

fn authorized(req: &Request, state: &State) -> bool {
    let Some(header) = &req.authorization else { return false };
    let Some((user, pass)) = basic_credentials(header) else { return false };
    user == state.moderator_username && pass == state.moderator_password
}

fn parse_id(s: &str) -> Option<i64> {
    s.parse::<i64>().ok().filter(|id| *id > 0)
}

fn moderate(req: &Request, conn: &mut Connection, segs: &[&str]) -> Resp {
    match (req.method.as_str(), segs) {
        // ---------- Quizzes ----------
        ("GET", ["moderate"]) => {
            let summaries = db::list_quizzes(conn).unwrap_or_default();
            Resp::html(views::quiz_list(&summaries))
        }
        // ---------- Export / import ----------
        ("GET", ["moderate", "import"]) => Resp::html(views::import_form("", &[])),
        ("POST", ["moderate", "import"]) => {
            let raw = req.param("quiz_json").unwrap_or("").to_string();
            match transfer::parse_import(&raw) {
                Err(errors) => Resp::html(views::import_form(&raw, &errors)),
                Ok(imported) => {
                    let questions: Vec<(String, bool, Vec<(String, bool)>)> = imported
                        .questions
                        .into_iter()
                        .map(|q| (q.text, q.active, q.options))
                        .collect();
                    match db::import_quiz(conn, &imported.title, &questions) {
                        Ok(id) => Resp::redirect(&format!("/moderate/quizzes/{id}")),
                        Err(_) => Resp::html(views::import_form(
                            &raw,
                            &["Something went wrong while saving the quiz. Nothing was imported.".to_string()],
                        )),
                    }
                }
            }
        }
        ("GET", ["moderate", "quizzes", "new"]) => {
            Resp::html(views::quiz_form(None, "", &[]))
        }
        ("POST", ["moderate", "quizzes"]) => {
            let title = req.param("title").unwrap_or("").trim().to_string();
            if title.is_empty() {
                return Resp::html(views::quiz_form(None, "", &["Enter a title".to_string()]));
            }
            let id = db::create_quiz(conn, &title).map_err(|_| ()).unwrap_or(0);
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        ("GET", ["moderate", "quizzes", id]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = db::list_questions(conn, id).unwrap_or_default();
            Resp::html(views::quiz_page(&quiz, &questions))
        }
        ("GET", ["moderate", "quizzes", id, "export"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = db::list_questions(conn, id).unwrap_or_default();
            Resp::html(views::export_page(&quiz, &transfer::export_json(&quiz, &questions)))
        }
        ("GET", ["moderate", "quizzes", id, "edit"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
 ",
  "output_tail": ".param("dir").unwrap_or("").to_string();
            let _ = db::move_question(conn, qid, &dir);
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        ("POST", ["moderate", "quizzes", id, "questions", qid, "active"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(qid) = parse_id(qid) else { return Resp::not_found() };
            let _ = db::set_question_active(conn, qid, req.has_param("active"));
            Resp::redirect(&format!("/moderate/quizzes/{id}"))
        }
        // ---------- Preview ----------
        ("GET", ["moderate", "quizzes", id, "preview"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = active_questions(conn, id);
            if questions.is_empty() {
                return Resp::html(views::preview_empty(&quiz));
            }
            let total = questions.len();
            let n = req.param("n").and_then(|v| v.parse::<usize>().ok()).unwrap_or(1).clamp(1, total);
            let score = req.param("score").and_then(|v| v.parse::<i64>().ok()).unwrap_or(0).clamp(0, total as i64);
            Resp::html(views::preview_question(&quiz, &questions[n - 1], n, total, score))
        }
        ("POST", ["moderate", "quizzes", id, "preview", "answer"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let questions = active_questions(conn, id);
            if questions.is_empty() {
                return Resp::html(views::preview_empty(&quiz));
            }
            let total = questions.len();
            let n = req.param("n").and_then(|v| v.parse::<usize>().ok()).unwrap_or(1);
            let score = req.param("score").and_then(|v| v.parse::<i64>().ok()).unwrap_or(0);
            let base = format!("/moderate/quizzes/{id}/preview");
            if n < 1 || n > total {
                return Resp::redirect(&base);
            }
            let q = &questions[n - 1];
            let option_id = req.param("option").and_then(parse_id);
            let Some(opt) = option_id.and_then(|oid| q.options.iter().find(|o| o.id == oid)) else {
                // Unknown option: just show the question again.
                return Resp::redirect(&format!("{base}?n={n}&score={score}"));
            };
            let new_score = (score + if opt.correct { 1 } else { 0 }).clamp(0, total as i64);
            Resp::html(views::preview_feedback(&quiz, q, n, total, opt.id, opt.correct, new_score))
        }
        ("GET", ["moderate", "quizzes", id, "preview", "score"]) => {
            let Some(id) = parse_id(id) else { return Resp::not_found() };
            let Some(quiz) = db::get_quiz(conn, id).ok().flatten() else { return Resp::not_found() };
            let total = active_questions(conn, id).len();
            let score = req.param("score").and_then(|v| v.parse::<i64>().ok()).unwrap_or(0).clamp(0, total as i64);
            Resp::html(views::preview_score(&quiz, score, total))
        }
        _ => Resp::not_found(),
    }
}

fn active_questions(conn: &Connection, quiz_id: i64) -> Vec<Question> {
    db::list_questions(conn, quiz_id)
        .unwrap_or_default()
        .into_iter()
        .filter(|q| q.active)
        .collect()
}

struct QuestionForm {
    text: String,
    rows: Vec<views::OptionRow>,
    active: bool,
}

fn read_question_form(req: &Request) -> QuestionForm {
    let count: usize = req.param("option_count").and_then(|v| v.parse().ok()).unwrap_or(0).min(100);
    let mut rows = Vec::with_capacity(count);
    for i in 1..=count {
        rows.push(views::OptionRow {
            text: req.param(&format!("option_text_{i}")).unwrap_or("").to_string(),
            correct: req.has_param(&format!("option_correct_{i}")),
        });
    }
    QuestionForm {
        text: req.param("question").unwrap_or("").to_string(),
        rows,
        active: req.has_param("active"),
    }
}

/// Apply the option rules. Returns the cleaned options or the error messages
/// to show above the form (nothing is saved in that case).
fn validate_question(form: &QuestionForm) -> Result<Vec<(String, bool)>, Vec<String>> {
    let mut errors = Vec::new();
    if form.text.trim().is_empty() {
        errors.push("Enter the question text".to_string());
    }
    let filled: Vec<&views::OptionRow> = form.rows.iter().filter(|r| !r.text.trim().is_empty()).collect();
    if filled.len() < 2 {
        errors.push("Add at least two options".to_string());
    }
    if !filled.iter().any(|r| r.correct) {
        errors.push("Mark at least one option as correct".to_string());
    }
    if errors.is_empty() {
        Ok(filled.iter().map(|r| (r.text.trim().to_string(), r.correct)).collect())
    } else {
        Err(errors)
    }
}
