"""Minimal Chrome DevTools Protocol driver (raw websocket, no dependencies)."""
import base64, hashlib, json, os, socket, struct, time, urllib.request

class WS:
    def __init__(self, url, timeout=30):
        assert url.startswith("ws://")
        rest = url[5:]
        hostport, _, path = rest.partition("/")
        host, _, port = hostport.partition(":")
        self.sock = socket.create_connection((host, int(port or 80)))
        self.sock.settimeout(timeout)
        key = base64.b64encode(os.urandom(16)).decode()
        req = (f"GET /{path} HTTP/1.1\r\nHost: {hostport}\r\nUpgrade: websocket\r\n"
               f"Connection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n")
        self.sock.sendall(req.encode())
        resp = b""
        while b"\r\n\r\n" not in resp:
            resp += self.sock.recv(4096)
        assert b"101" in resp.split(b"\r\n")[0], resp
        self.buf = b""

    def _read_exact(self, n):
        while len(self.buf) < n:
            chunk = self.sock.recv(65536)
            if not chunk:
                raise ConnectionError("ws closed")
            self.buf += chunk
        out, self.buf = self.buf[:n], self.buf[n:]
        return out

    def recv_msg(self):
        while True:
            b1, b2 = self._read_exact(2)
            opcode = b1 & 0x0F
            masked = b2 & 0x80
            ln = b2 & 0x7F
            if ln == 126:
                ln = struct.unpack(">H", self._read_exact(2))[0]
            elif ln == 127:
                ln = struct.unpack(">Q", self._read_exact(8))[0]
            mask = self._read_exact(4) if masked else None
            payload = self._read_exact(ln) if ln else b""
            if mask:
                payload = bytes(c ^ mask[i % 4] for i, c in enumerate(payload))
            if opcode == 1:
                return payload.decode()
            if opcode == 8:
                raise ConnectionError("ws close frame")
            # ping/pong/continuation: ignore (messages are small enough)

    def send_msg(self, text):
        data = text.encode()
        header = bytearray([0x81])
        ln = len(data)
        if ln < 126:
            header.append(0x80 | ln)
        elif ln < 65536:
            header.append(0x80 | 126)
            header += struct.pack(">H", ln)
        else:
            header.append(0x80 | 127)
            header += struct.pack(">Q", ln)
        mask = os.urandom(4)
        header += mask
        masked = bytes(c ^ mask[i % 4] for i, c in enumerate(data))
        self.sock.sendall(bytes(header) + masked)

class Tab:
    def __init__(self, ws_url):
        self.ws = WS(ws_url)
        self.next_id = 1

    def cmd(self, method, params=None):
        mid = self.next_id
        self.next_id += 1
        self.ws.send_msg(json.dumps({"id": mid, "method": method, "params": params or {}}))
        while True:
            msg = json.loads(self.ws.recv_msg())
            if msg.get("id") == mid:
                if "error" in msg:
                    raise RuntimeError(f"{method}: {msg['error']}")
                return msg.get("result", {})

    def navigate(self, url):
        self.cmd("Page.enable")
        self.cmd("Page.navigate", {"url": url})
        time.sleep(0.6)

    def js(self, expr):
        r = self.cmd("Runtime.evaluate", {"expression": expr, "returnByValue": True, "awaitPromise": True})
        if "exceptionDetails" in r:
            raise RuntimeError(f"JS error: {r['exceptionDetails']}")
        return r.get("result", {}).get("value")

    def text(self):
        return self.js("document.body.innerText")

    def html(self):
        return self.js("document.documentElement.outerHTML")

    def click_text(self, selector, label):
        ok = self.js(f"""(() => {{
            const els = [...document.querySelectorAll({json.dumps(selector)})];
            const el = els.find(e => e.textContent.trim() === {json.dumps(label)});
            if (!el) return false;
            el.click();
            return true;
        }})()""")
        return ok

    def wait_text(self, needle, timeout=8):
        deadline = time.time() + timeout
        while time.time() < deadline:
            if needle in self.text():
                return True
            time.sleep(0.25)
        return False

def launch(port=9222, extra=()):
    import subprocess
    proc = subprocess.Popen([
        "chromium", "--headless=new", f"--remote-debugging-port={port}",
        "--no-sandbox", "--disable-gpu", "--disable-dev-shm-usage",
        "--user-data-dir=/tmp/qa/chrome-profile-" + str(port), *extra, "about:blank",
    ], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
    for _ in range(50):
        try:
            urllib.request.urlopen(f"http://localhost:{port}/json/version", timeout=1)
            break
        except Exception:
            time.sleep(0.2)
    return proc

def new_tab(port, url="about:blank"):
    req = urllib.request.Request(f"http://localhost:{port}/json/new?{urllib.request.quote(url)}", method="PUT")
    info = json.loads(urllib.request.urlopen(req, timeout=5).read())
    return Tab(info["webSocketDebuggerUrl"])
